import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {setLogger, type Logger} from '../../shared/logger.js';

const locationInputSchema = {
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location'],
};

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger();
    jest.restoreAllMocks();
  });

  it('rejects missing required input', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: locationInputSchema,
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({
      namesRequiredProperty: /location.*required|required.*location/i.test(response.result),
      executorCalls,
    }).toEqual({namesRequiredProperty: true, executorCalls: 0});
  });

  it('names the full path of a missing nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response.result).toMatch(/location\.city.*required|required.*location\.city/i);
  });

  it('rejects a wrong type without exposing its value in the response or logs', async () => {
    const registry = new ToolRegistry();
    const identifyingValue = 'private-user@example.com';
    let executorCalls = 0;
    const logLines: string[] = [];
    const testLogger: Logger = {
      debug: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      info: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      warn: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      error: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
    };
    setLogger(testLogger);
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'number'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {location: identifyingValue as unknown as number});
    expect({
      namesPath: response.result.includes('location'),
      namesExpectedType: response.result.includes('number'),
      hidesValueFromResult: !response.result.includes(identifyingValue),
      hidesValueFromLogs: !logLines.join('\n').includes(identifyingValue),
      executorCalls,
    }).toEqual({
      namesPath: true,
      namesExpectedType: true,
      hidesValueFromResult: true,
      hidesValueFromLogs: true,
      executorCalls: 0,
    });
  });

  it('rejects an enum value and names the field and constraint', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_mode',
        description: 'Set operating mode',
        inputSchema: {
          type: 'object',
          properties: {mode: {type: 'string', enum: ['safe', 'fast']}},
          required: ['mode'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'set';
      }
    );

    const response = await registry.execute('set_mode', {mode: 'unsafe'});

    expect({
      executorCalls,
      namesField: response.result.includes('mode'),
      namesConstraint: /enum|allowed value/i.test(response.result),
    }).toEqual({executorCalls: 0, namesField: true, namesConstraint: true});
  });

  it('passes valid input with extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'celsius'};
    let executorCalls = 0;
    let passedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: locationInputSchema,
      },
      async receivedInput => {
        executorCalls += 1;
        passedInput = receivedInput;
        return 'sunny';
      }
    );

    await registry.execute('weather', input);

    expect({calls: executorCalls, input: passedInput}).toEqual({calls: 1, input});
  });

  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    const schemas = [
      {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      {type: 'object', properties: {postalCode: {type: 'number'}}, required: ['postalCode']},
    ];
    let definitionCalls = 0;
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Weather with a changing input schema',
        inputSchema: schemas[definitionCalls++ === 2 ? 1 : 0],
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const first = await registry.execute('dynamic_weather', {city: 'Berlin'});
    const second = await registry.execute('dynamic_weather', {postalCode: '10115'});

    expect({
      firstAccepted: first.result === 'sunny',
      secondNamesPath: second.result.includes('postalCode'),
      secondNamesExpectedType: second.result.includes('number'),
      executorCalls,
    }).toEqual({
      firstAccepted: true,
      secondNamesPath: true,
      secondNamesExpectedType: true,
      executorCalls: 1,
    });
  });

  it('throws at registration when a static schema is invalid and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'broken_weather', description: 'Invalid schema', inputSchema: {type: 'not-a-json-schema-type'}},
        async () => 'sunny'
      )
    ).toThrow(/broken_weather/);
  });

  it('compiles a static schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'Get weather', inputSchema: locationInputSchema},
      async () => 'sunny'
    );
    const {calls: registrationCalls} = compile.mock;
    const compileCallsAfterRegistration = registrationCalls.length;

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Berlin'});
    }

    const {calls: executionCalls} = compile.mock;
    expect({compileCallsAfterRegistration, compileCallsAfterExecutions: executionCalls.length}).toEqual({
      compileCallsAfterRegistration: 1,
      compileCallsAfterExecutions: 1,
    });
  });

  it('logs schema rejection details without input values', async () => {
    const registry = new ToolRegistry();
    const identifyingValue = 'private-user@example.com';
    const logLines: string[] = [];
    const testLogger: Logger = {
      debug: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      info: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      warn: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      error: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
    };
    setLogger(testLogger);
    registry.register(
      {
        name: 'lookup_user',
        description: 'Look up a user',
        inputSchema: {
          type: 'object',
          properties: {userId: {type: 'number'}},
          required: ['userId'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_user', {userId: identifyingValue as unknown as number});
    const emittedLogs = logLines.join('\n');

    expect({
      responseNamesPath: response.result.includes('userId'),
      responseNamesConstraint: response.result.includes('number'),
      logsNamePath: emittedLogs.includes('userId'),
      logsNameConstraint: emittedLogs.includes('number'),
      hidesValue: !`${response.result}\n${emittedLogs}`.includes(identifyingValue),
    }).toEqual({
      responseNamesPath: true,
      responseNamesConstraint: true,
      logsNamePath: true,
      logsNameConstraint: true,
      hidesValue: true,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects missing required input](../../src/orchestration/tools/registry.test.ts#L18), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When a nested object omits a required property, the rejection names its complete field path ([validated by: names the full path of a missing nested required property](../../src/orchestration/tools/registry.test.ts#L42)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, logs the field path and constraint, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: logs schema rejection details without input values](../../src/orchestration/tools/registry.test.ts#L139)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the field path and expected type without exposing the offending value in the response or logs ([validated by: rejects a wrong type without exposing its value in the response or logs](../../src/orchestration/tools/registry.test.ts#L41), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` supplies a value outside a property's declared `enum`, `ToolRegistry.execute` returns a rejection naming the property and the enum constraint without invoking the executor ([validated by: rejects an enum value and names the field and constraint](../../src/orchestration/tools/registry.test.ts#L85)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with extra properties to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L139)).
- A schema rejection is logged with the failing property path and constraint, without including the rejected property value ([validated by: logs schema rejection details without input values](../../src/orchestration/tools/registry.test.ts#L231)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at registration when a static schema is invalid and names the tool](../../src/orchestration/tools/registry.test.ts#L198), [validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L209)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each function-valued definition against its current schema](../../src/orchestration/tools/registry.test.ts#L136)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
